-- STRICTLY READ ONLY. Run after 202608280002 is manually applied.
with function_state as (
  select pg_get_functiondef('public.rebuild_oil_supplier_accounting(uuid)'::regprocedure) definition
  where to_regprocedure('public.rebuild_oil_supplier_accounting(uuid)') is not null
), checks(check_name,status,details,blocking) as (
  values
  ('REBUILD_RPC_EXISTS',case when to_regprocedure('public.rebuild_oil_supplier_accounting(uuid)') is not null then 'PASS' else 'FAIL' end,'Expected rebuild RPC signature',true),
  ('FIRST_PAYMENT_ALIAS_COLLISION_REMOVED',case when exists(select 1 from function_state where definition ~* 'payment_row[[:space:]]+record' and definition ~* 'using[[:space:]]+public[.]oil_supplier_payments[[:space:]]+payment_source' and definition !~* 'p[[:space:]]+record') then 'PASS' else 'FAIL' end,'Loop record and SQL relation aliases are distinct; empty-history/first-payment path no longer reads an unassigned record',true),
  ('FIFO_CONTRACT',case when exists(select 1 from function_state where definition ~* 'order by[[:space:]]+payment_date,created_at,id' and definition ~* 'order by[[:space:]]+bill_date,created_at,id') then 'PASS' else 'FAIL' end,'Payment rebuild and bill allocation remain deterministic FIFO',true),
  ('CASHBOOK_PAYMENT_NOW_ONLY',case when exists(select 1 from function_state where definition ~* 'coalesce[(]payment_row[.]payment_now,0[)]>0' and definition ~* '''oil_supplier_payment''' and definition ~* 'payment_row[.]payment_now') then 'PASS' else 'FAIL' end,'Only persisted payment_now is synchronized to Oil supplier Cashbook reference',true),
  ('REBUILD_SECURITY',case when exists(select 1 from pg_proc where oid=to_regprocedure('public.rebuild_oil_supplier_accounting(uuid)') and prosecdef and array_to_string(proconfig,',') like '%search_path=public, pg_temp%') then 'PASS' else 'FAIL' end,'SECURITY DEFINER and locked search_path preserved',true),
  ('REBUILD_NOT_BROWSER_EXECUTABLE',case when not has_function_privilege('authenticated','public.rebuild_oil_supplier_accounting(uuid)','EXECUTE') and not has_function_privilege('anon','public.rebuild_oil_supplier_accounting(uuid)','EXECUTE') then 'PASS' else 'FAIL' end,'Internal rebuild remains unavailable directly to browser roles',true),
  ('SAVE_RPC_SECURITY_AND_GRANTS',case when exists(select 1 from pg_proc where oid=to_regprocedure('public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)') and prosecdef and array_to_string(proconfig,',') like '%search_path=public, pg_temp%') and has_function_privilege('authenticated','public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') and not has_function_privilege('anon','public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') then 'PASS' else 'FAIL' end,'Save RPC security and authenticated-only execution preserved',true),
  ('THREE_SUPPLIER_BILLS_PRESERVED',case when (select count(*) from public.oil_supplier_bills)=3 then 'PASS' else 'FAIL' end,(select format('%s supplier bill(s) present; expected confirmed count is 3',count(*)) from public.oil_supplier_bills),true),
  ('NO_DUPLICATE_SUPPLIER_BILLS',case when not exists(select 1 from public.oil_supplier_bills group by source_type,coalesce(oil_purchase_id::text,oil_vehicle_entry_id::text) having count(*)>1) then 'PASS' else 'FAIL' end,'No authoritative Oil source has duplicate supplier bills',true),
  ('NO_ORPHAN_PAYMENTS',case when not exists(select 1 from public.oil_supplier_payments p left join public.oil_shops s on s.id=p.oil_shop_id where s.id is null) then 'PASS' else 'FAIL' end,'Every payment resolves to its supplier',true),
  ('NO_ORPHAN_ALLOCATIONS',case when not exists(select 1 from public.oil_supplier_payment_allocations a left join public.oil_supplier_payments p on p.id=a.payment_id left join public.oil_supplier_bills b on b.id=a.supplier_bill_id where p.id is null or b.id is null) then 'PASS' else 'FAIL' end,'Every allocation resolves to a payment and bill',true),
  ('BILL_ACCOUNTING_INVARIANTS',case when not exists(select 1 from public.oil_supplier_bills where amount<=0 or paid_amount<0 or remaining_amount<0 or paid_amount+remaining_amount<>amount or payment_status<>case when remaining_amount=0 then 'paid' when paid_amount>0 then 'partial' else 'unpaid' end) then 'PASS' else 'FAIL' end,'Bill paid plus remaining equals authoritative amount and status agrees',true),
  ('PAYMENT_ACCOUNTING_INVARIANTS',case when not exists(select 1 from public.oil_supplier_payments where advance_used<0 or payment_now<0 or amount<>advance_used+payment_now or remaining_payable<0 or remaining_advance<0) then 'PASS' else 'FAIL' end,'Payment settlement snapshots remain non-negative and amount is normalized',true),
  ('CASHBOOK_UNIQUENESS_INDEX',case when to_regclass('public.cashbook_entries_oil_supplier_reference_uidx') is not null then 'PASS' else 'FAIL' end,'Oil supplier Cashbook unique reference index preserved',true),
  ('NO_DUPLICATE_CASHBOOK_REFERENCES',case when not exists(select 1 from public.cashbook_entries where reference_type='oil_supplier_payment' group by reference_id having count(*)>1) then 'PASS' else 'FAIL' end,'No duplicate automatic supplier payment Cashbook rows',true),
  ('CASHBOOK_AMOUNT_MATCH',case when not exists(select 1 from public.oil_supplier_payments p join public.cashbook_entries c on c.reference_type='oil_supplier_payment' and c.reference_id=p.id::text where c.amount<>p.payment_now) then 'PASS' else 'FAIL' end,'Existing automatic Cashbook amounts match payment_now',true),
  ('COUNTS','INFO',(select format('%s bills; %s payments; %s allocations; %s Oil supplier Cashbook rows',(select count(*) from public.oil_supplier_bills),(select count(*) from public.oil_supplier_payments),(select count(*) from public.oil_supplier_payment_allocations),(select count(*) from public.cashbook_entries where reference_type='oil_supplier_payment'))),false)
), combined as (
  select 'OVERALL_OIL_SUPPLIER_FIRST_PAYMENT_FIX_POST_VERIFY'::text check_name,
    case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,
    format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details
  from checks
  union all select check_name,status,details from checks
)
select check_name,status,details from combined
order by case when check_name='OVERALL_OIL_SUPPLIER_FIRST_PAYMENT_FIX_POST_VERIFY' then 0 else 1 end,check_name;
